diff --git a/rust/ews_xpcom/src/client.rs b/rust/ews_xpcom/src/client.rs
index 3c6f8c30251..5ec223e2d65 100644
--- a/rust/ews_xpcom/src/client.rs
+++ b/rust/ews_xpcom/src/client.rs
@@ -446,6 +446,7 @@ where
                         "item:HasAttachments",
                         "item:Importance",
                         "message:References",
+                        "item:Size",
                     ],
                     false,
                 )
@@ -1859,6 +1860,17 @@ fn populate_db_message_header_from_message_headers(
         unsafe { header.SetReferences(&*references) }.to_result()?;
     }

+    if let Some(size) = msg.size() {
+        match size.try_into() {
+            Ok(size) => {
+                unsafe { header.SetMessageSize(size) }.to_result()?;
+            }
+            Err(_) => {
+                log::error!("failed to compute size for message that's larger than supported max size of {}", u32::MAX);
+            }
+        };
+    }
+
     Ok(())
 }

